<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <cstdio>
#include <vector>
using namespace std;

long long modExp(long long base, long long exp, long long mod) {
    long long result = 1;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

int main() {
    int P, K;
    scanf("%d %d", &P, &K);

    if (K == 0) {
        printf("%lld\n", modExp(P, P - 1, 1000000007));
        return 0;
    }
    if (K == 1) {
        printf("%lld\n", modExp(P, P, 1000000007));
        return 0;
    }

    vector<bool> visited(P, false);
    int cycle_length = 0;
    int p = 1;
    while (!visited[p]) {
        visited[p] = true;
        cycle_length++;
        p = (long long)K * p % P;
    }

    printf("%lld\n", modExp(P, cycle_length, 1000000007));
    return 0;
}
</original_code>
